B.aiJ=new A.V(B.af,["\xbfC\xf3mo modifico las fechas de mi reserva?","Las modificaciones est\xe1n sujetas a disponibilidad. Contacta con nosotros al menos 48h antes y gestionamos el cambio de fechas sin complicaciones."],t.w)
B.aiv=new A.V(B.af,["\xbfOfrecen garant\xeda de precio m\xe1s bajo?","S\xed. Si encuentras el mismo hotel a menor precio en otro sitio web dentro de las 24h tras reservar, te igualamos el precio sin preguntas."],t.w)
B.aiR=new A.V(B.af,["\xbfEs seguro pagar en SkyTrip?","Todos los pagos se procesan con cifrado SSL y cumplimos con PCI-DSS. Nunca almacenamos datos de tarjetas bancarias en nuestros servidores."],t.w)
B.a89=s([B.aiK,B.aiY,B.aiJ,B.aiv,B.aiR],t.J)
B.aiW=new A.V(B.af,["Explora el mundo con SkyTrip","Descubre cientos de destinos en todo el mundo. Filtra por pa\xeds y encuentra el alojamiento perfecto para cada aventura."],t.w)
B.aj8=new A.V(B.af,["Destinos recomendados","Cada semana actualizamos nuestra selecci\xf3n de destinos m\xe1s populares con las mejores ofertas disponibles."],t.w)
